  'camp.suppressedUnsubscribedAccountNote': 'ಈ ವ್ಯಕ್ತಿ ಈಗಾಗಲೇ {sender} ನಿಂದ ಅನ್‌ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಆಗಿದ್ದಾರೆ — ಈ ಖಾತೆ ಅವರಿಗೆ ಇನ್ನೆಂದೂ ಇಮೇಲ್ ಕಳುಹಿಸುವುದಿಲ್ಲ, ಮರುಕಳುಹಿಸುವಿಕೆ ಇದನ್ನು ಬದಲಾಯಿಸುವುದಿಲ್ಲ. ಈ ವರ್ಕ್‌ಸ್ಪೇಸ್‌ನ ಇತರ ಕಳುಹಿಸುವ ಖಾತೆಗಳು ಇನ್ನೂ ಅವರನ್ನು ತಲುಪಬಹುದು.',
