  'camp.suppressedBouncedNote': 'ಈ ವಿಳಾಸ ಈ ಹಿಂದೆ ಬೌನ್ಸ್ ಆಗಿತ್ತು ಅಥವಾ ಸ್ಪ್ಯಾಮ್ ಎಂದು ಗುರುತಿಸಲಾಗಿತ್ತು, ಮತ್ತು ಭವಿಷ್ಯದ ಎಲ್ಲಾ ಕಳುಹಿಸುವಿಕೆಗಳಿಂದ ತಡೆಯಲಾಗಿದೆ. ಮರುಕಳುಹಿಸುವಿಕೆ ಇದನ್ನು ಬದಲಾಯಿಸುವುದಿಲ್ಲ.',
