  'tpl.design.socialLinksHelp': 'ಸರಳ, ಕ್ಲಿಕ್ ಮಾಡಬಹುದಾದ ಪಠ್ಯ ಲಿಂಕ್ ಆಗಿ ತೋರಿಸಲಾಗುತ್ತದೆ (ಉದಾ. "Instagram") — ಒಂದು ಚಿತ್ರ ಐಕಾನ್ ಆಗಿ ಎಂದಿಗೂ ಅಲ್ಲ, ಆದ್ದರಿಂದ ಇದು ಪ್ರತಿ ಇಮೇಲ್ ಆ್ಯಪ್‌ನಲ್ಲೂ ಯಾವಾಗಲೂ ಕೆಲಸ ಮಾಡುತ್ತದೆ. ಪ್ರತಿಯೊಂದಕ್ಕೂ ತನ್ನದೇ {{key}} ಸಿಗುತ್ತದೆ — ಎಲ್ಲಿ ಬೇಕಾದರೂ ಇಡಲು ಡೈನಾಮಿಕ್ ಫೀಲ್ಡ್ ಸೇರಿಸಿ ಬಳಸಿ.',
  'tpl.design.unsubscribeText': 'ಅನ್‌ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಲಿಂಕ್ ಪಠ್ಯ',
  'tpl.design.unsubscribeHelp': 'ಅನ್‌ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಲಿಂಕ್ ಕಾಣಿಸಬೇಕೆಂದಿರುವ ಎಲ್ಲಿಯಾದರೂ ಅದರ {{key}} ಅನ್ನು ಸೇರಿಸಿ. ಇದನ್ನು ಬಿಟ್ಟುಬಿಟ್ಟರೂ, ಪ್ರತಿ ಇಮೇಲ್ ಒಂದು ನಿಜವಾದ, ಕೆಲಸ ಮಾಡುವ ಅನ್‌ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಲಿಂಕ್‌ನೊಂದಿಗೆ ತಾನಾಗಿಯೇ ಕಳುಹಿಸಲಾಗುತ್ತದೆ — ಆದ್ದರಿಂದ ಸ್ವೀಕರಿಸುವವರು ಯಾವಾಗಲೂ ಆಯ್ಕೆಯಿಂದ ಹೊರಗುಳಿಯಬಹುದು.',
  'tpl.design.categoryPlaceholder': 'ಇರುವ ವರ್ಗವನ್ನು ಆಯ್ಕೆ ಮಾಡಿ ಅಥವಾ ಹೊಸದನ್ನು ಟೈಪ್ ಮಾಡಿ',
  'tpl.design.categoryHelp': 'ಹೊಸ ಹೆಸರು ಟೈಪ್ ಮಾಡುವುದು ಆ ವರ್ಗವನ್ನು ರಚಿಸುತ್ತದೆ — ಇದು ಟೆಂಪ್ಲೇಟ್ ಪುಟದಲ್ಲಿ ಒಂದು ಟ್ಯಾಬ್ ಆಗಿ ಕಾಣಿಸುತ್ತದೆ.',
  'tpl.design.readyMade': 'ಸಿದ್ಧ ಟೆಂಪ್ಲೇಟ್‌ಗಳು',
