  'dyn.insertField': 'ಡೈನಾಮಿಕ್ ಫೀಲ್ಡ್ ಸೇರಿಸಿ',
  'dyn.manageFields': 'ಡೈನಾಮಿಕ್ ಫೀಲ್ಡ್‌ಗಳು',
  'dyn.managerTitle': 'ಡೈನಾಮಿಕ್ ಫೀಲ್ಡ್‌ಗಳು',
  'dyn.howItWorks': 'ಡೈನಾಮಿಕ್ ಫೀಲ್ಡ್‌ಗಳು ತಾಂತ್ರಿಕ ಪಠ್ಯವನ್ನು ನೆನಪಿಡುವ ಬದಲು "Customer Name" ನಂತಹ ಸ್ನೇಹಪರ ಹೆಸರನ್ನು ಬರೆಯಲು ಅನುಮತಿಸುತ್ತವೆ. ಅಭಿಯಾನ ಕಳುಹಿಸಿದಾಗ, ಇದು ಪ್ರತಿ ಸ್ವೀಕರಿಸುವವರ ನಿಜವಾದ ಮೌಲ್ಯದೊಂದಿಗೆ ತಾನಾಗಿಯೇ ಬದಲಾಗುತ್ತದೆ — ಉದಾಹರಣೆಗೆ, "Customer Name" ನೇಹಾಗೆ "Neha Kulkarni" ಆಗುತ್ತದೆ ಮತ್ತು ಅಮಿತ್‌ಗೆ "Amit Shah" ಆಗುತ್ತದೆ. ತಾಂತ್ರಿಕ ವೇರಿಯಬಲ್ ಅನ್ನು ಇಲ್ಲಿ ಹೆಚ್ಚುವರಿ ವಿವರವಾಗಿ ಮಾತ್ರ ತೋರಿಸಲಾಗುತ್ತದೆ; ನೀವು ಅದನ್ನು ಎಂದಿಗೂ ಸ್ವತಃ ಟೈಪ್ ಮಾಡಬೇಕಾಗಿಲ್ಲ.',
  'dyn.builtinTitle': 'ಅಂತರ್ನಿರ್ಮಿತ ಫೀಲ್ಡ್‌ಗಳು',
  'dyn.customTitle': 'ನಿಮ್ಮ ಕಸ್ಟಮ್ ಫೀಲ್ಡ್‌ಗಳು',
  'dyn.customHelp': 'ಮೇಲೆ ಪಟ್ಟಿ ಮಾಡದ ಯಾವುದಕ್ಕಾದರೂ (ಉದಾ. "Order Number") ನಿಮ್ಮ ಸ್ವಂತ ಫೀಲ್ಡ್ ಸೇರಿಸಿ. ನಿಮ್ಮ ಡೇಟಾದಲ್ಲಿ ಆ ಮೌಲ್ಯ ಸೇರುವವರೆಗೆ ಇದು ಸುರಕ್ಷಿತವಾಗಿ ಖಾಲಿಯಾಗಿ ಸೇರುತ್ತದೆ.',
