  'acc.multipleNote': 'ನಿಮಗೆ ಬೇಕಾದಷ್ಟು ವಿಳಾಸಗಳನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು — ಮೂರು Outlook ಮೇಲ್‌ಬಾಕ್ಸ್‌ಗಳು, ಒಂದು Gmail ಮತ್ತು ಒಂದು SMTP, ಯಾವುದೇ ಮಿಶ್ರಣದಲ್ಲಿ. ಪ್ರತಿ ಸಂಪರ್ಕವೂ ಪ್ರತ್ಯೇಕವಾಗಿದ್ದು ತನ್ನದೇ ಕಳುಹಿಸುವ ಮಿತಿಯನ್ನು ಇಟ್ಟುಕೊಳ್ಳುತ್ತದೆ, ಮತ್ತು ಪ್ರತಿ ಅಭಿಯಾನವೂ ಅವುಗಳಲ್ಲಿ ಒಂದನ್ನು ತನ್ನ ಕಳುಹಿಸುವವರಾಗಿ ಆಯ್ಕೆ ಮಾಡುತ್ತದೆ.',

