  'users.pwdLinkText': '"ಪಾಸ್‌ವರ್ಡ್ ಮರೆತಿರಾ?" ಕಳುಹಿಸುವ ಅದೇ ಇಮೇಲ್ ಕಳುಹಿಸುತ್ತದೆ, ಆದ್ದರಿಂದ ನೀವು ಅವರ ಪಾಸ್‌ವರ್ಡ್ ಅನ್ನು ಎಂದಿಗೂ ನಿಭಾಯಿಸುವುದಿಲ್ಲ.',
