  'users.pwdLinkSent': 'ಈ ವ್ಯಕ್ತಿಯ ಇಮೇಲ್‌ಗೆ ರೀಸೆಟ್ ಲಿಂಕ್ ಕಳುಹಿಸಲಾಗಿದೆ.',

  // --- System emails -------------------------------------------------------
  'nav.systemEmails': 'ಸಿಸ್ಟಂ ಇಮೇಲ್‌ಗಳು',
  'sysmail.title': 'ಸಿಸ್ಟಂ ಇಮೇಲ್‌ಗಳು',
  'sysmail.subtitle': 'ಆ್ಯಪ್ ಸ್ವತಃ ಕಳುಹಿಸುವ ಇಮೇಲ್‌ಗಳು — ಆಹ್ವಾನಗಳು, ಪಾಸ್‌ವರ್ಡ್ ರೀಸೆಟ್, ಎಚ್ಚರಿಕೆಗಳು ಮತ್ತು ವರದಿಗಳು.',
  'sysmail.intro': 'ಇವು ಅಭಿಯಾನಗಳಲ್ಲ. ಪ್ರತಿಯೊಂದೂ ಒಂದು ಘಟನೆಯಿಂದ ಪ್ರಚೋದಿಸಲ್ಪಡುತ್ತದೆ, ಮತ್ತು ವಿನ್ಯಾಸ ಈಗಾಗಲೇ ಬರೆಯಲಾಗಿದೆ. ಬ್ಯಾಕೆಂಡ್ ನಿರ್ಮಾಣವಾದಾಗ, ಪ್ರತಿ ಘಟನೆಗೂ ಕೇವಲ ಒಂದು ಸಾಲು ಸಾಕು — ವಿಷಯ ಮತ್ತು HTML ಇಲ್ಲಿಂದಲೇ ಬರುತ್ತವೆ.',
  'sysmail.list': 'ಪ್ರತಿ ಸಿಸ್ಟಂ ಇಮೇಲ್',
  'sysmail.listSub': 'ಮುನ್ನೋಟ ಅಥವಾ ಸಂಪಾದಿಸಲು ಒಂದನ್ನು ಆಯ್ಕೆ ಮಾಡಿ',
  'sysmail.group': 'ಗುಂಪು',
  'sysmail.language': 'ಭಾಷೆ',
  'sysmail.fallbackNote': 'ಇನ್ನೂ {language} ಆವೃತ್ತಿ ಉಳಿಸಿಲ್ಲ — ಕೆಳಗೆ ಇಂಗ್ಲಿಷ್ ವಿಷಯ ತೋರಿಸಲಾಗುತ್ತಿದೆ. ಒಂದನ್ನು ರಚಿಸಲು ಸಂಪಾದಿಸಿ ಮತ್ತು ಉಳಿಸಿ.',
  'sysmail.removeTranslation': 'ಈ ಭಾಷೆಯ ಆವೃತ್ತಿಯನ್ನು ತೆಗೆದುಹಾಕಿ',
