  'sysmail.previewNote': 'ಮುನ್ನೋಟವು ಮಾದರಿ ಮೌಲ್ಯಗಳೊಂದಿಗೆ ವೇರಿಯಬಲ್‌ಗಳನ್ನು ಭರ್ತಿ ಮಾಡುತ್ತದೆ ಆದ್ದರಿಂದ ನೀವು ಇದನ್ನು ನಿಜವಾದ ಇಮೇಲ್‌ನಂತೆ ಓದಬಹುದು.',
