  'sysmail.variablesHelp': 'ವಿಷಯ ಅಥವಾ HTMLನಲ್ಲಿ ಒಂದು ವೇರಿಯಬಲ್ ಬರೆಯಿರಿ ಮತ್ತು ಕಳುಹಿಸುವಾಗ ನಿಜವಾದ ಮೌಲ್ಯ ಸೇರುತ್ತದೆ.',
  'sysmail.reset': 'ಮೂಲಕ್ಕೆ ಮರುಹೊಂದಿಸಿ',
