  'sysmail.criticalNote': 'ಇದನ್ನು ಆಫ್ ಮಾಡಲಾಗುವುದಿಲ್ಲ — ಜನರು ತಮ್ಮ ಸ್ವಂತ ಖಾತೆಯಿಂದಲೇ ಲಾಕ್ ಆಗಿಬಿಡುತ್ತಾರೆ.',
  'sysmail.optionalNote': 'ನಿಮ್ಮ ತಂಡಕ್ಕೆ ಇದು ಹೆಚ್ಚು ಇಮೇಲ್ ಎನಿಸಿದರೆ ಇದನ್ನು ಆಫ್ ಮಾಡಬಹುದು.',
  'sysmail.forDevs': 'ಬ್ಯಾಕೆಂಡ್ ಇದನ್ನು ಹೇಗೆ ಕಳುಹಿಸುತ್ತದೆ',
  'sysmail.adminOnly': 'ಸೂಪರ್ ಅಡ್ಮಿನ್ ಮಾತ್ರ ಈ ಪುಟವನ್ನು ತೆರೆಯಬಹುದು.',
  'sysmail.statusOn': 'ಸಕ್ರಿಯ',
  'sysmail.statusOff': 'ನಿಷ್ಕ್ರಿಯ',
  'sysmail.sendTest': 'ಪರೀಕ್ಷೆ ಕಳುಹಿಸಿ',
  'sysmail.testNote': 'ಇದು ಹೇಗೆ ಕಾಣುತ್ತದೆ ಎಂದು ನೋಡಲು ನಿಮ್ಮ ಸ್ವಂತ ಇಮೇಲ್‌ಗೆ ಒಂದು ಮಾದರಿ ಕಳುಹಿಸುತ್ತದೆ — ಮೇಲಿನ ಸ್ವಿಚ್ ಆಫ್ ಆಗಿದ್ದರೂ ಇದು ಕೆಲಸ ಮಾಡುತ್ತದೆ, ಮತ್ತು ಸ್ವಯಂಚಾಲಿತ ಕಳುಹಿಸುವಿಕೆಯನ್ನು ಆನ್ ಮಾಡುವುದಿಲ್ಲ.',
  'sysmail.testSentTo': '{email} ಗೆ ಪರೀಕ್ಷೆ ಕಳುಹಿಸಲಾಗಿದೆ',

  'help.sysmail.1': 'ಆ್ಯಪ್ ಸ್ವತಃ ಕಳುಹಿಸುವ ಪ್ರತಿ ಇಮೇಲ್ ಅನ್ನು ಅದನ್ನು ಪ್ರಚೋದಿಸುವ ಘಟನೆಯೊಂದಿಗೆ ಇಲ್ಲಿ ಪಟ್ಟಿ ಮಾಡಲಾಗಿದೆ.',
  'help.sysmail.2': 'ಯಾವುದೇ ಟೆಂಪ್ಲೇಟ್‌ನಂತೆ ವಿಷಯ ಮತ್ತು HTML ಸಂಪಾದಿಸಿ. ಪಾಸ್‌ವರ್ಡ್ ಇಮೇಲ್‌ಗಳನ್ನು ಆಫ್ ಮಾಡಲಾಗುವುದಿಲ್ಲ.',

  'theme.title': 'ನೋಟ ಮತ್ತು ಶೈಲಿ',
  'theme.subtitle': 'ಹಗಲು ಅಥವಾ ರಾತ್ರಿ, ಮತ್ತು ಆ್ಯಪ್ ನಿರ್ಮಾಣಗೊಂಡಿರುವ ಬಣ್ಣ.',
  'theme.mode': 'ಹಗಲು / ರಾತ್ರಿ',
  'theme.light': 'ಹಗಲು',
  'theme.dark': 'ರಾತ್ರಿ',
  'theme.system': 'ನನ್ನ ಕಂಪ್ಯೂಟರ್‌ಗೆ ಹೊಂದಿಸಿ',
  'theme.colour': 'ಮುಖ್ಯ ಬಣ್ಣ',
  'theme.help': 'ನಿಮ್ಮ ಆಯ್ಕೆ ಈ ಸಾಧನದಲ್ಲಿ ಮಾತ್ರ ಉಳಿಸಲ್ಪಡುತ್ತದೆ. ಇತರರು ನೋಡುವುದನ್ನು ಇದು ಬದಲಾಯಿಸುವುದಿಲ್ಲ.',
  'theme.indigo': 'ಇಂಡಿಗೋ',
  'theme.blue': 'ನೀಲಿ',
  'theme.teal': 'ಟೀಲ್',
  'theme.green': 'ಹಸಿರು',
  'theme.amber': 'ಅಂಬರ್',
  'theme.rose': 'ಗುಲಾಬಿ',
  'theme.purple': 'ನೇರಳೆ',
  'theme.slate': 'ಬೂದು',
  'theme.brandNote': 'ಆ್ಯಪ್ ಹೆಸರು, ಟ್ಯಾಗ್‌ಲೈನ್ ಮತ್ತು ಲೋಗೋ ಎಲ್ಲವೂ ಒಂದೇ ಫೈಲ್‌ನಿಂದ ಬರುತ್ತವೆ — src/config/appConfig.js. ಅಲ್ಲಿ ಒಮ್ಮೆ ಬದಲಾಯಿಸಿದರೆ ಸೈಡ್‌ಬಾರ್, ಲಾಗಿನ್ ಪುಟ, ಬ್ರೌಸರ್ ಟ್ಯಾಬ್ ಮತ್ತು ಮುನ್ನೋಟ ಪುಟಗಳೆಲ್ಲಾ ಅನುಸರಿಸುತ್ತವೆ.',
  'set.appearance': 'ನೋಟ ಮತ್ತು ಶೈಲಿ',
