  'bulk.doneSuppress': 'ಇನ್ನೆಂದೂ-ಇಮೇಲ್-ಬೇಡ ಪಟ್ಟಿಗೆ {count} ವಿಳಾಸಗಳನ್ನು ಸೇರಿಸಲಾಗಿದೆ.',
  'bulk.confirmRemoveTitle': 'ಈ ಸ್ವೀಕರಿಸುವವರನ್ನು ತೆಗೆದುಹಾಕಬೇಕೇ?',
  'bulk.confirmRemoveText': 'ಇದು ಈ ಅಭಿಯಾನದ ಪಟ್ಟಿಯಿಂದ {count} ಜನರನ್ನು ತೆಗೆದುಹಾಕುತ್ತದೆ. ಇದು ಅವರ ಸಂಪರ್ಕ ದಾಖಲೆಯನ್ನು ಮುಟ್ಟುವುದಿಲ್ಲ ಅಥವಾ ಏನನ್ನೂ ಕಳುಹಿಸುವುದಿಲ್ಲ.',
  'bulk.confirmSuppressTitle': 'ಈ ಜನರಿಗೆ ಇನ್ನೆಂದೂ ಇಮೇಲ್ ಮಾಡಬಾರದೇ?',
  'bulk.confirmSuppressText': 'ಇದು ನಿಗ್ರಹ ಪಟ್ಟಿಗೆ {count} ವಿಳಾಸಗಳನ್ನು ಸೇರಿಸುತ್ತದೆ. ಭವಿಷ್ಯದ ಪ್ರತಿ ಅಭಿಯಾನವೂ ಅವರನ್ನು ತಾನಾಗಿಯೇ ಬಿಟ್ಟುಬಿಡುತ್ತದೆ — ಇದನ್ನು ಇಲ್ಲಿಂದ ಹಿಂತಿರುಗಿಸಲಾಗುವುದಿಲ್ಲ.',
