  'sample.colEmail': 'ಇಮೇಲ್ ವಿಳಾಸ. ಪ್ರತಿ ಸಾಲಿಗೂ ಈ ಕಾಲಮ್ ಭರ್ತಿಯಾಗಿರಬೇಕು.',
