  'send.title': 'ಕಳುಹಿಸುವಿಕೆ ಮತ್ತು ಟ್ರ್ಯಾಕಿಂಗ್',
  'send.subtitle': 'ಚಿಕ್ಕ ಬ್ಯಾಚ್‌ಗಳು ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಪೂರೈಕೆದಾರರೊಂದಿಗೆ ಸುರಕ್ಷಿತವಾಗಿಡುತ್ತವೆ ಮತ್ತು ಉತ್ತಮ ವಿತರಣೆ ನೀಡುತ್ತವೆ.',
  'send.batchSize': 'ಬ್ಯಾಚ್ ಗಾತ್ರ',
