  'send.batchPer': 'ಪ್ರತಿ ಬ್ಯಾಚ್‌ಗೆ {size}',
  'send.batchPlan': '{count} ಸ್ವೀಕರಿಸುವವರು {batches} ಬ್ಯಾಚ್‌ಗಳಲ್ಲಿ ಹೋಗುತ್ತಾರೆ:',
  'send.batchLabel': 'ಬ್ಯಾಚ್ {number} → {size}',
