  'send.delayLabel': 'ಬ್ಯಾಚ್‌ಗಳ ನಡುವೆ ಕಾಯುವಿಕೆ: {minutes} ನಿಮಿಷಗಳು',
  'send.delayHelp': 'ಸ್ವಲ್ಪ ಕಾಯುವಿಕೆ ನಿಮ್ಮ ಪೂರೈಕೆದಾರರ ಪ್ರಕಟಿತ ಕಳುಹಿಸುವ ಮಿತಿಗಳೊಳಗೆ ನಿಮ್ಮನ್ನು ಇರಿಸುತ್ತದೆ. ನಾವು ಎಂದಿಗೂ ಅವುಗಳನ್ನು ಮೀರಲು ಪ್ರಯತ್ನಿಸುವುದಿಲ್ಲ.',
  'send.estimateUnderMinute': 'ಒಂದು ನಿಮಿಷಕ್ಕಿಂತ ಕಡಿಮೆ',
  'send.estimateMinutes': '{minutes} ನಿಮಿ',
  'send.estimateHours': '{hours} ಗಂ',
  'send.estimateHoursMinutes': '{hours} ಗಂ {minutes} ನಿಮಿ',
  'send.estimateSameDay': '≈ {batches} ಬ್ಯಾಚ್‌ಗಳಲ್ಲಿ {duration} — ಎಲ್ಲವೂ ಇಂದು.',
  'send.estimateQuotaLimited': '≈ {days} ದಿನಗಳು — {account} ಕೇವಲ {limit}/ದಿನ ಕಳುಹಿಸಬಹುದು, ಆದ್ದರಿಂದ ಕಳುಹಿಸುವಿಕೆ ಪ್ರತಿ ದಿನ ತಾನಾಗಿಯೇ ವಿರಾಮಗೊಂಡು ಮುಂದುವರಿಯುತ್ತದೆ. ಬ್ಯಾಚ್‌ಗಳ ನಡುವೆ ಸುಮಾರು {duration} ನಿಜವಾದ ಕಾಯುವ ಸಮಯ.',
  'send.estimateSampleLabel': 'ಎಷ್ಟು ಸ್ವೀಕರಿಸುವವರಿಗೆ ಅಂದಾಜು?',
  'send.estimateAccountNote': 'ಇದು ಒಂದು ಸ್ಥೂಲ ಅಂದಾಜು (ಬ್ಯಾಚ್ ಗಾತ್ರ × ಕಾಯುವ ಸಮಯ ಮಾತ್ರ). ನಿಜವಾದ ಸಂಖ್ಯೆ ಯಾವ ಇಮೇಲ್ ಖಾತೆ ಅದನ್ನು ಕಳುಹಿಸುತ್ತದೆ ಮತ್ತು ಆ ಖಾತೆಯ ದೈನಂದಿನ ಮಿತಿಯ ಮೇಲೆ ಅವಲಂಬಿತವಾಗಿದೆ — ನಿಖರವಾದ ಅಂದಾಜಿಗೆ ಅಭಿಯಾನ ವಿಝಾರ್ಡ್‌ನಲ್ಲಿ ನಿಜವಾದ ಪ್ರೇಕ್ಷಕರನ್ನು ಆಯ್ಕೆ ಮಾಡಿ.',
  'send.openTracking': 'ತೆರೆಯುವಿಕೆ ಟ್ರ್ಯಾಕಿಂಗ್',
  'send.openTrackingDesc': 'ತೆರೆಯುವಿಕೆಗಳನ್ನು ಅಂದಾಜಿಸಲು ಒಂದು ಸಣ್ಣ ಕಾಣದ ಚಿತ್ರ ಸೇರಿಸುತ್ತದೆ. ಫಲಿತಾಂಶಗಳು ಒಂದು ಅಂದಾಜು — ಕೆಲವು ಮೇಲ್ ಆ್ಯಪ್‌ಗಳು ಚಿತ್ರವನ್ನು ತಡೆಯುತ್ತವೆ, ಮತ್ತು ಪ್ರೈವಸಿ ಪ್ರಾಕ್ಸಿಗಳು ಎಂದೂ ಸಂಭವಿಸದ ಒಂದು ತೆರೆಯುವಿಕೆಯನ್ನು ಎಣಿಸಬಹುದು.',
  'send.clickTracking': 'ಕ್ಲಿಕ್ ಟ್ರ್ಯಾಕಿಂಗ್',
  'send.clickTrackingDesc': 'ಕ್ಲಿಕ್‌ಗಳನ್ನು ಎಣಿಸಬಹುದಾಗುವಂತೆ ಈ ಅಭಿಯಾನದಲ್ಲಿನ ಲಿಂಕ್‌ಗಳನ್ನು ಪುನಃ ಬರೆಯುತ್ತದೆ. ಡೀಫಾಲ್ಟ್ ಆಗಿ ಆಫ್ — ನೀವು ಪ್ರತಿ ಅಭಿಯಾನಕ್ಕೂ ಇದನ್ನು ಆನ್ ಮಾಡುತ್ತೀರಿ.',
  'send.subscribeButton': 'ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಬಟನ್',
  'send.subscribeTitle': 'ಈ ಇಮೇಲ್‌ಗೆ ಒಂದು Subscribe ಬಟನ್ ಸೇರಿಸಿ',
  'send.subscribeDesc': 'ಕೆಲವು ಇಮೇಲ್‌ಗಳು ಇನ್ನೂ ನಿಮ್ಮ ಪಟ್ಟಿಯಲ್ಲಿ ಇಲ್ಲದ ಜನರಿಗೆ ಹೋಗುತ್ತವೆ. ಒಂದು Subscribe ಬಟನ್ ಅವರಿಗೆ ಹೆಚ್ಚು ಕೇಳಲು ಅವಕಾಶ ಕೊಡುತ್ತದೆ. ಅದನ್ನು ಒತ್ತುವ ಯಾರಾದರೂ ನಿಮ್ಮ Subscribers ಪುಟಕ್ಕೆ ಬರುತ್ತಾರೆ, ಈ ಅಭಿಯಾನದ ಹೆಸರಿನೊಂದಿಗೆ — ಆದ್ದರಿಂದ ಅವರು ಎಲ್ಲಿಂದ ಬಂದರು ಎಂದು ನಿಮಗೆ ಯಾವಾಗಲೂ ತಿಳಿಯುತ್ತದೆ.',
  'send.subscribeNote': '{{subscribe_url}} ಅನ್ನು ನಿಮ್ಮ HTMLನಲ್ಲಿ ಎಲ್ಲಿಯಾದರೂ ಇಡಿ ಮತ್ತು ಅದು ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಲಿಂಕ್ ಆಗುತ್ತದೆ. ನೀವು ಅದನ್ನು ಬಿಟ್ಟುಬಿಟ್ಟರೆ, ನಾವು ಫೂಟರ್‌ಗಿಂತ ಮೇಲೆ ನಿಮಗಾಗಿ ಒಂದು ಚಿಕ್ಕ ಬಟನ್ ಸೇರಿಸುತ್ತೇವೆ.',
  'send.whenTitle': 'ಇದು ಯಾವಾಗ ಹೋಗಬೇಕು?',
  'send.now': 'ಈಗಲೇ ಕಳುಹಿಸಿ',
  'send.nowDesc': 'ನೀವು ದೃಢೀಕರಿಸಿದ ತಕ್ಷಣ ಕಳುಹಿಸುವಿಕೆ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ.',
  'send.later': 'ನಂತರಕ್ಕೆ ನಿಗದಿಪಡಿಸಿ',
  'send.laterDesc': 'ಒಂದು ದಿನಾಂಕ ಮತ್ತು ಸಮಯ ಆಯ್ಕೆ ಮಾಡಿ. ನಾವು ಅದನ್ನು ನಿಮಗಾಗಿ ಸರತಿಗೆ ಸೇರಿಸುತ್ತೇವೆ.',
  'send.dateTime': 'ದಿನಾಂಕ ಮತ್ತು ಸಮಯ',
  'send.queueNote': 'ಕಳುಹಿಸುವಿಕೆ ನಮ್ಮ ಸರ್ವರ್ ಸರತಿಯಲ್ಲಿ ನಡೆಯುತ್ತದೆ. ನೀವು ಈ ಟ್ಯಾಬ್ ಅಥವಾ ನಿಮ್ಮ ಲ್ಯಾಪ್‌ಟಾಪ್ ಮುಚ್ಚಬಹುದು — ಅಭಿಯಾನ ಮುಂದುವರಿಯುತ್ತದೆ, ಮತ್ತು ನೀವು ಯಾವಾಗ ಬೇಕಾದರೂ ಅದನ್ನು ವಿರಾಮಗೊಳಿಸಬಹುದು.',

