  'acc.connectedWho': '{email} ಸಂಪರ್ಕಗೊಂಡಿದೆ',
  'acc.connectedNote': 'ನಾವು ನಿಮಗೆ ಒಂದೇ ಒಂದು ಸರ್ವರ್ ಸೆಟ್ಟಿಂಗ್ ಕೂಡ ತೋರಿಸಲಿಲ್ಲ — ಮತ್ತು ಎಂದಿಗೂ ತೋರಿಸುವುದಿಲ್ಲ. ಸೈನ್-ಇನ್ ನೇರವಾಗಿ ಪೂರೈಕೆದಾರರೊಂದಿಗೆ ನಡೆಯಿತು.',
  'acc.goToAccounts': 'ಇಮೇಲ್ ಖಾತೆಗಳಿಗೆ ಹೋಗಿ',
  'acc.tokenNote': 'Google ಮತ್ತು Microsoft ನೊಂದಿಗೆ ನೀವು ಅವರ ಸ್ವಂತ ಪುಟದಲ್ಲಿ ಸೈನ್ ಇನ್ ಮಾಡುತ್ತೀರಿ. {app} ನಿಮ್ಮ ಪಾಸ್‌ವರ್ಡ್ ಅನ್ನು ಎಂದಿಗೂ ನೋಡುವುದಿಲ್ಲ ಅಥವಾ ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ — ಕೇವಲ ಒಂದು ಟೋಕನ್, ನಮ್ಮ ಸರ್ವರ್‌ನಲ್ಲಿ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿ ಇಡಲಾಗಿದೆ.',
  'acc.provider.google': 'Google ನೊಂದಿಗೆ ಒಂದೇ-ಕ್ಲಿಕ್ ಸೈನ್ ಇನ್. ಭರ್ತಿ ಮಾಡಲು ಯಾವುದೇ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಲ್ಲ.',
  'acc.provider.microsoft': 'ನಿಮ್ಮ Microsoft ಕೆಲಸ ಅಥವಾ ವೈಯಕ್ತಿಕ ಖಾತೆಯೊಂದಿಗೆ ಸೈನ್ ಇನ್ ಮಾಡಿ.',
  'acc.provider.sendgrid': 'ಹೆಚ್ಚಿನ-ಪ್ರಮಾಣದ ಕಳುಹಿಸುವಿಕೆಗಾಗಿ ಒಂದು API ಕೀಯೊಂದಿಗೆ ಸಂಪರ್ಕಿಸಿ.',
  'acc.provider.mailgun': 'ನಿಮ್ಮ Mailgun ಡೊಮೇನ್ ಮತ್ತು API ಕೀ ಸಂಪರ್ಕಿಸಿ.',
  'acc.provider.ses': 'ನಿಮ್ಮ AWS SES ಪ್ರದೇಶ ಮತ್ತು ಕ್ರೆಡೆನ್ಷಿಯಲ್‌ಗಳನ್ನು ಬಳಸಿ.',
  'acc.provider.smtp': 'ಇತರ ಯಾವುದೇ ಪೂರೈಕೆದಾರ. ನಾವು ಒಂದೊಂದೇ ಫೀಲ್ಡ್‌ನಲ್ಲಿ ನಿಮಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತೇವೆ.',
  'acc.credTitle': 'ನಿಮ್ಮ ಕ್ರೆಡೆನ್ಷಿಯಲ್‌ಗಳನ್ನು ಹೇಗೆ ಇಡಲಾಗುತ್ತದೆ',
  'acc.credSub': 'ಚಿಕ್ಕ ಆವೃತ್ತಿ, ಸರಳ ಪದಗಳಲ್ಲಿ',
  'acc.credHidden': 'ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಎಂದಿಗೂ ತೋರಿಸಲಾಗುವುದಿಲ್ಲ.',
  'acc.credHiddenText': 'ಪಾಸ್‌ವರ್ಡ್‌ಗಳು, API ಕೀಗಳು ಮತ್ತು OAuth ಟೋಕನ್‌ಗಳು ಸರ್ವರ್‌ನಲ್ಲಿ ಉಳಿಯುತ್ತವೆ. ಈ ಪರದೆ ಎಂದಿಗೂ ಕೇವಲ ಒಂದು ಸಂಪರ್ಕ ಸ್ಥಿತಿಯನ್ನು ಮಾತ್ರ ನೋಡುತ್ತದೆ.',
  'acc.credEncrypted': 'ವಿಶ್ರಾಂತಿಯಲ್ಲಿ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿದೆ.',
  'acc.credEncryptedText': 'AES-256 ನೊಂದಿಗೆ ಸಂಗ್ರಹಿಸಲಾಗಿದೆ, ಕೀಯನ್ನು ಒಂದು secrets manager ನಲ್ಲಿ ಇಡಲಾಗಿದೆ — ಎಂದಿಗೂ ಕೋಡ್‌ನ ಒಳಗೆ ಅಲ್ಲ.',
  'acc.credRefreshed': 'ನಿಮಗಾಗಿ ರಿಫ್ರೆಶ್ ಆಗುತ್ತದೆ.',
  'acc.credRefreshedText': 'ಮುಗಿದ OAuth ಟೋಕನ್‌ಗಳನ್ನು ಸರ್ವರ್‌ನಲ್ಲಿ ನವೀಕರಿಸಲಾಗುತ್ತದೆ. ಪ್ರತಿ ವಾರವೂ ನೀವು ಮತ್ತೆ ಸೈನ್ ಇನ್ ಮಾಡಬೇಕಾಗಿಲ್ಲ.',
  'acc.limitNote': 'ಪ್ರತಿ ಪೂರೈಕೆದಾರರಿಗೂ ತನ್ನದೇ ದೈನಂದಿನ ಕಳುಹಿಸುವ ಮಿತಿ ಇದೆ. {app} ಆ ಮಿತಿಗಳ ಒಳಗೇ ಇರುತ್ತದೆ ಮತ್ತು ಅವುಗಳನ್ನು ಮೀರುವ ಬದಲು ನಿಧಾನಗೊಳಿಸುತ್ತದೆ.',
