  'set.retryDesc': 'ತಾತ್ಕಾಲಿಕ ಪೂರೈಕೆದಾರ ದೋಷ 15 ನಿಮಿಷಗಳ ನಂತರ ಮರುಪ್ರಯತ್ನಿಸಲಾಗುತ್ತದೆ. ಹಾರ್ಡ್ ಬೌನ್ಸ್‌ಗಳನ್ನು ಎಂದಿಗೂ ಮರುಪ್ರಯತ್ನಿಸಲಾಗುವುದಿಲ್ಲ.',
  'set.quietTitle': 'ಶಾಂತ ಸಮಯಗಳನ್ನು ಗೌರವಿಸಿ (ರಾತ್ರಿ 9 – ಬೆಳಿಗ್ಗೆ 8)',
  'set.quietDesc': 'ಸರತಿಯಲ್ಲಿರುವ ಇಮೇಲ್‌ಗಳು ಸ್ವೀಕರಿಸುವವರ ಟೈಮ್ ಝೋನ್‌ನಲ್ಲಿ ಬೆಳಗ್ಗಿನವರೆಗೆ ಕಾಯುತ್ತವೆ.',
  'set.sendingNote': 'ಇಲ್ಲಿ ನೀವು ಹೊಂದಿಸುವ ಬ್ಯಾಚ್ ಗಾತ್ರ ಮತ್ತು ವಿಳಂಬ ಪ್ರತಿ ಹೊಸ ಅಭಿಯಾನದ ಆರಂಭಿಕ ಬಿಂದುವಾಗುತ್ತದೆ — ನೀವು ಇನ್ನೂ ವಿಝಾರ್ಡ್‌ನಲ್ಲಿ ಪ್ರತಿ ಅಭಿಯಾನಕ್ಕೂ ಅವುಗಳನ್ನು ಬದಲಾಯಿಸಬಹುದು. ಮರುಪ್ರಯತ್ನ ಪ್ರತಿ ಅಭಿಯಾನಕ್ಕೂ ತಾನಾಗಿಯೇ ಅನ್ವಯಿಸುತ್ತದೆ. ಶಾಂತ ಸಮಯಗಳನ್ನು ಒಂದು ಆದ್ಯತೆಯಾಗಿ ಉಳಿಸಲಾಗುತ್ತದೆ; ಕಳುಹಿಸುವ ಎಂಜಿನ್ ಇನ್ನೂ ಅದರ ಮೇಲೆ ಕಾರ್ಯನಿರ್ವಹಿಸುವುದಿಲ್ಲ.',
