  'set.trackingSub': 'ನಾವು ಏನನ್ನು ದಾಖಲಿಸುತ್ತೇವೆ, ಮತ್ತು ಏನನ್ನು ಮಾಡುವುದಿಲ್ಲ',
  'set.openDefaultTitle': 'ಡೀಫಾಲ್ಟ್ ಆಗಿ ತೆರೆಯುವಿಕೆ ಟ್ರ್ಯಾಕಿಂಗ್ ಆನ್',
  'set.openDefaultDesc': 'ತೆರೆಯುವಿಕೆಗಳನ್ನು ಅಂದಾಜಿಸಲು ಒಂದು ಕಾಣದ ಚಿತ್ರ ಸೇರಿಸುತ್ತದೆ. ನೀವು ಇನ್ನೂ ಪ್ರತಿ ಅಭಿಯಾನಕ್ಕೂ ಇದನ್ನು ಆಫ್ ಮಾಡಬಹುದು.',
  'set.clickDefaultTitle': 'ಡೀಫಾಲ್ಟ್ ಆಗಿ ಕ್ಲಿಕ್ ಟ್ರ್ಯಾಕಿಂಗ್ ಆನ್',
  'set.clickDefaultDesc': 'ಕ್ಲಿಕ್‌ಗಳನ್ನು ಎಣಿಸಬಹುದಾಗುವಂತೆ ಲಿಂಕ್‌ಗಳನ್ನು ಪುನಃ ಬರೆಯುತ್ತದೆ. ಸರಳ ಲಿಂಕ್‌ಗಳನ್ನು ಬಯಸಿದರೆ ಇದನ್ನು ಆಫ್ ಮಾಡಿ.',
  'set.deviceTitle': 'ಸಾಧನ ಪ್ರಕಾರ ದಾಖಲಿಸಿ',
  'set.deviceDesc': 'ಕಚ್ಚಾ ಬ್ರೌಸರ್/ಮೇಲ್-ಆ್ಯಪ್ ಸ್ಟ್ರಿಂಗ್ ಈಗಾಗಲೇ ಯಾವಾಗಲೂ ಪ್ರತಿ ತೆರೆಯುವಿಕೆ ಮತ್ತು ಕ್ಲಿಕ್‌ನೊಂದಿಗೆ ಸಂಗ್ರಹವಾಗಿದೆ — ಈ ಸ್ವಿಚ್ ಇನ್ನೂ ಅದನ್ನು ಬದಲಾಯಿಸುವುದಿಲ್ಲ.',
  'set.locationTitle': 'ಅಂದಾಜು ಸ್ಥಳ ದಾಖಲಿಸಿ',
  'set.locationDesc': 'IP ವಿಳಾಸ ಈಗಾಗಲೇ ಯಾವಾಗಲೂ ಸಂಗ್ರಹವಾಗಿದೆ — ಈ ಸ್ವಿಚ್ ಇನ್ನೂ ದೇಶದ ಹೆಸರನ್ನು ಆನ್ ಅಥವಾ ಆಫ್ ಮಾಡುವುದಿಲ್ಲ, ಏಕೆಂದರೆ ಒಂದು lookup ಹಂತ ಇನ್ನೂ ಅಸ್ತಿತ್ವದಲ್ಲಿಲ್ಲ.',
  'set.openEstimateNote': 'ತೆರೆಯುವಿಕೆ ಎಣಿಕೆಗಳು ಯಾವಾಗಲೂ ಒಂದು ಅಂದಾಜು. ಚಿತ್ರ ತಡೆಗಟ್ಟುವಿಕೆ ನಿಜವಾದ ತೆರೆಯುವಿಕೆಗಳನ್ನು ಮರೆಮಾಡುತ್ತದೆ, ಮತ್ತು ಪ್ರೈವಸಿ ಪ್ರಾಕ್ಸಿಗಳು ಎಂದೂ ಸಂಭವಿಸದ ತೆರೆಯುವಿಕೆಗಳನ್ನು ಸೃಷ್ಟಿಸುತ್ತವೆ. ಈ ಕಾರಣಕ್ಕೆ ನಾವು ಪ್ರತಿ ತೆರೆಯುವಿಕೆಯನ್ನೂ "ತೆರೆಯುವಿಕೆ ಪತ್ತೆಯಾಗಿದೆ" ಎಂದು ಲೇಬಲ್ ಮಾಡುತ್ತೇವೆ.',
  'set.trackingNote': 'ತೆರೆಯುವಿಕೆ ಮತ್ತು ಕ್ಲಿಕ್ ಟ್ರ್ಯಾಕಿಂಗ್ ಡೀಫಾಲ್ಟ್‌ಗಳು ನಿಜವಾಗಿಯೂ ಪ್ರತಿ ಹೊಸ ಅಭಿಯಾನಕ್ಕೂ ಅನ್ವಯಿಸುತ್ತವೆ (ನೀವು ಇನ್ನೂ ಪ್ರತಿ ಅಭಿಯಾನಕ್ಕೂ ಇದನ್ನು ಮೀರಿಸಬಹುದು). ಸಾಧನ ಮತ್ತು ಸ್ಥಳ ಸದ್ಯಕ್ಕೆ ಕೇವಲ ಒಂದು ಆದ್ಯತೆಯಾಗಿ ಉಳಿಸಲಾಗುತ್ತದೆ — ಈ ಎರಡು ಸ್ವಿಚ್‌ಗಳ ಹೊರತಾಗಿಯೂ ಕಚ್ಚಾ user-agent ಮತ್ತು IP ಪ್ರತಿ ತೆರೆಯುವಿಕೆಯಲ್ಲೂ ದಾಖಲಾಗುತ್ತದೆ.',
