  'set.templateOptionsSub': 'ಯಾವ ಟೆಂಪ್ಲೇಟ್ ರಚನಾ ವಿಧಾನಗಳು ಲಭ್ಯವಿವೆ ಎಂದು ಆಯ್ಕೆ ಮಾಡಿ',
  'set.templateOptionsNote': 'ಒಂದು ವಿಧಾನವನ್ನು ಆಫ್ ಮಾಡುವುದು ಅದನ್ನು ಮಾತ್ರ ಮರೆಮಾಡುತ್ತದೆ — ಹೊಸ ಟೆಂಪ್ಲೇಟ್‌ಗಳು, ಮತ್ತು ಅವು ಎಲ್ಲೆಲ್ಲಿ ಪಟ್ಟಿಯಾಗಿವೆ — ಏನೂ ಎಂದಿಗೂ ಅಳಿಸಲಾಗುವುದಿಲ್ಲ. ಆ ಪ್ರಕಾರದ ಇರುವ ಟೆಂಪ್ಲೇಟ್‌ಗಳು ಸುರಕ್ಷಿತವಾಗಿ ಉಳಿಯುತ್ತವೆ ಮತ್ತು ನೀವು ಅದನ್ನು ಮತ್ತೆ ಆನ್ ಮಾಡಿದ ಕ್ಷಣ ಮತ್ತೆ ಕಾಣಿಸುತ್ತವೆ.',
