  'set.contactsNote': 'ಆಮದಿನಲ್ಲಿ ನಕಲುಗಳನ್ನು ತೆಗೆದುಹಾಕುವುದು ಈಗಾಗಲೇ ಯಾವಾಗಲೂ ಸಂಭವಿಸುತ್ತದೆ — ಇದು ಐಚ್ಛಿಕವಲ್ಲ. ಇತರ ಎರಡನ್ನೂ ಒಂದು ಆದ್ಯತೆಯಾಗಿ ಉಳಿಸಲಾಗುತ್ತದೆ; ಆಮದು ಪರದೆಗೆ ಸಮ್ಮತಿ ಇನ್ನೂ ಅಗತ್ಯವಿಲ್ಲ, ಮತ್ತು ಕಸ್ಟಮ್ ಫೀಲ್ಡ್‌ಗಳನ್ನು ಟೆಂಪ್ಲೇಟ್‌ಗಳಲ್ಲಿ ಮರ್ಜ್ ವೇರಿಯಬಲ್‌ಗಳಾಗಿ ಇನ್ನೂ ನೀಡಲಾಗುವುದಿಲ್ಲ.',
