  'set.unsubGlobalDesc': 'ಆಫ್ (ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ): ಒಂದು ಕಳುಹಿಸುವ ಖಾತೆಯಿಂದ ಅನ್‌ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಮಾಡುವುದು ಆ ಖಾತೆಯಿಂದ ಮಾತ್ರ ಭವಿಷ್ಯದ ಇಮೇಲ್‌ಗಳನ್ನು ತಡೆಯುತ್ತದೆ — ಈ ವರ್ಕ್‌ಸ್ಪೇಸ್‌ನ ಇತರ ಖಾತೆಗಳು ಇನ್ನೂ ಅವರಿಗೆ ಇಮೇಲ್ ಮಾಡಬಹುದು. ಆನ್: ಒಂದು ಅನ್‌ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಪ್ರತಿ ಕಳುಹಿಸುವ ಖಾತೆಯನ್ನೂ ತಡೆಯುತ್ತದೆ.',
  'set.unsubNote': 'ಅನ್‌ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಆದ ಜನರು ಆ ಕಳುಹಿಸುವ ಖಾತೆಯ ನಿಗ್ರಹ ಪಟ್ಟಿಯಲ್ಲಿ ಹೋಗುತ್ತಾರೆ ಮತ್ತು ಆ ಖಾತೆಯ ಭವಿಷ್ಯದ ಅಭಿಯಾನಗಳಿಂದ ತಾನಾಗಿಯೇ ತೆಗೆದುಹಾಕಲಾಗುತ್ತದೆ.',
