  'set.storageSecretHelp': 'ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿ ಸಂಗ್ರಹಿಸಲಾಗಿದೆ. ಉಳಿಸಿದ ನಂತರ ಇನ್ನೆಂದೂ ತೋರಿಸಲಾಗುವುದಿಲ್ಲ — ಇತರ ಫೀಲ್ಡ್‌ಗಳನ್ನು ಮಾತ್ರ ಬದಲಾಯಿಸುತ್ತಿದ್ದರೆ ಇದನ್ನು ಖಾಲಿ ಬಿಡಿ.',
