  'set.storageDisconnected': 'ಸಂಗ್ರಹಣೆ ಸಂಪರ್ಕ ಕಡಿತಗೊಂಡಿದೆ',
  'set.storageDisconnectConfirmTitle': 'Image Storage ಸಂಪರ್ಕ ಕಡಿತಗೊಳಿಸಬೇಕೇ?',
  'set.storageDisconnectConfirmText': 'ಇದು ಉಳಿಸಿದ ಕ್ರೆಡೆನ್ಷಿಯಲ್‌ಗಳನ್ನು ಮಾತ್ರ ತೆಗೆದುಹಾಕುತ್ತದೆ — ಈಗಾಗಲೇ ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ಚಿತ್ರಗಳನ್ನು ಎಂದಿಗೂ ಅಳಿಸಲಾಗುವುದಿಲ್ಲ. ನೀವು ಮತ್ತೆ ಸಂಗ್ರಹಣೆ ಸಂಪರ್ಕಿಸುವವರೆಗೆ ಹೊಸ ಅಪ್‌ಲೋಡ್‌ಗಳು ಈ ಆ್ಯಪ್‌ನ ಸ್ವಂತ ಡೇಟಾಬೇಸ್‌ಗೆ ಹಿಂತಿರುಗುತ್ತವೆ.',

