  'set.imgStoreDbTitle': 'DB ಇಮೇಜ್ ಸ್ಟೋರೇಜ್',
  'set.imgStoreDbDesc': 'ಹೊಸ ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ಚಿತ್ರಗಳನ್ನು ಈ ಆ್ಯಪ್‌ನ ಸ್ವಂತ ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ನೇರವಾಗಿ ಸಂಗ್ರಹಿಸಿ.',
  'set.imgStoreExternalTitle': 'ಬಾಹ್ಯ ಇಮೇಜ್ ಸ್ಟೋರೇಜ್',
  'set.imgStoreExternalDesc': 'ಹೊಸ ಅಪ್‌ಲೋಡ್‌ಗಳಿಗೆ ನಿಮ್ಮ ಸಂಪರ್ಕಿತ ಬಾಹ್ಯ ಸಂಗ್ರಹಣಾ ಪೂರೈಕೆದಾರ (ಮೇಲೆ, Storage ಅಡಿಯಲ್ಲಿ ಹೊಂದಿಸಲಾಗಿದೆ) ಬಳಸಿ.',
  'set.imageStorageNote': 'ಎರಡನ್ನೂ ಆಫ್ ಮಾಡುವುದು ಸ್ಪಷ್ಟ ಸಂದೇಶದೊಂದಿಗೆ ಹೊಸ ಅಪ್‌ಲೋಡ್‌ಗಳನ್ನು ತಡೆಯುತ್ತದೆ — ಇರುವ ಚಿತ್ರಗಳನ್ನು ಎರಡೂ ರೀತಿಯಲ್ಲಿ ಎಂದಿಗೂ ಅಳಿಸಲಾಗುವುದಿಲ್ಲ, ಸರಿಸಲಾಗುವುದಿಲ್ಲ, ಅಥವಾ ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ. ಇಲ್ಲಿ External ಅನ್ನು ಅವಲಂಬಿಸುವ ಮೊದಲು Storage ಅಡಿಯಲ್ಲಿ ಒಂದು ಪೂರೈಕೆದಾರರನ್ನು ಸಂಪರ್ಕಿಸಿ.',

