  'set.backupMaxStorageUnit': 'ಘಟಕ',
  'set.backupNote': 'ಧಾರಣ ಅವಧಿಗಿಂತ ಹಳೆಯ ಮಾಸಿಕ ಬ್ಯಾಕಪ್‌ಗಳನ್ನು ತಾನಾಗಿಯೇ ತೆಗೆದುಹಾಕಲಾಗುತ್ತದೆ. ಒಟ್ಟು ಸಂಗ್ರಹಣೆ ಮಿತಿ ಮೀರಿದರೆ, ಅರ್ಹ ಹಳೆಯ ದೈನಂದಿನ ಬ್ಯಾಕಪ್‌ಗಳನ್ನು ಮೊದಲು ತೆಗೆದುಹಾಕಲಾಗುತ್ತದೆ — ಇತ್ತೀಚಿನ ಬ್ಯಾಕಪ್ ಮತ್ತು ಈ ತಿಂಗಳ ಬ್ಯಾಕಪ್ ನಿರ್ಮಿಸಲು ಇನ್ನೂ ಅಗತ್ಯವಿರುವ ಯಾವುದನ್ನೂ ಎಂದಿಗೂ ಮುಟ್ಟಲಾಗುವುದಿಲ್ಲ.',

  'set.webhooksSub': 'ಏನಾದರೂ ಸಂಭವಿಸಿದ ಕ್ಷಣ ಇತರ ಟೂಲ್‌ಗಳಿಗೆ ಒಂದು ಸಂದೇಶ ಕಳುಹಿಸಿ — ಯಾವುದೇ ಡೆವಲಪರ್ ಅಗತ್ಯವಿಲ್ಲ',
  'set.webhooksIntro': 'ಪ್ರತಿ ಬಾರಿ ಒಂದು ಇಮೇಲ್ ಕಳುಹಿಸಿದಾಗ, ತೆರೆದಾಗ, ಕ್ಲಿಕ್ ಮಾಡಿದಾಗ, ಅಥವಾ ಯಾರಾದರೂ ಅನ್‌ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಮಾಡಿದಾಗ, {app} ಸಂಭವಿಸಿದ ಕ್ಷಣವೇ ನೀವು ಆಯ್ಕೆ ಮಾಡುವ ವೆಬ್ ವಿಳಾಸಕ್ಕೆ ಒಂದು ಸಣ್ಣ ಸಂದೇಶ ಕಳುಹಿಸಬಹುದು.',
