  'set.webhooksNoCodeText': 'Zapier, Make.com ಅಥವಾ Pabbly Connect ತೆರೆಯಿರಿ, ಹೊಸ ಆಟೊಮೇಶನ್ ಪ್ರಾರಂಭಿಸಿ, ಮತ್ತು "Webhooks" ಅಥವಾ "Catch Hook" ಎಂಬ ಟ್ರಿಗರ್ ಆಯ್ಕೆ ಮಾಡಿ. ಇದು ನಿಮಗೆ ಒಂದು ವೆಬ್ ವಿಳಾಸ ಕೊಡುತ್ತದೆ — ಆ ವಿಳಾಸವನ್ನು ಕೆಳಗೆ ಪೇಸ್ಟ್ ಮಾಡಿ, ಇದನ್ನು ಆನ್ ಮಾಡಿ, ಮತ್ತು ಉಳಿಸಿ ಒತ್ತಿ. ಇಡೀ ಸೆಟಪ್ ಅಷ್ಟೇ.',
