  'set.rotateSecretConfirmText': 'ನೀವು ಅಥವಾ ಒಬ್ಬ ಡೆವಲಪರ್ ಸ್ವೀಕರಿಸುವ ಕಡೆಯಲ್ಲಿ ಈ ಸೀಕ್ರೆಟ್ ಅನ್ನು ಪರಿಶೀಲಿಸುತ್ತಿದ್ದರೆ, ನೀವು ಅಲ್ಲಿಯೂ ಅದನ್ನು ನವೀಕರಿಸುವವರೆಗೆ ಆ ಪರಿಶೀಲನೆ ವಿಫಲಗೊಳ್ಳಲು ಪ್ರಾರಂಭಿಸುತ್ತದೆ. Zapier ನಂತಹ ಟೂಲ್‌ಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ.',
