  'seg.new': 'ಹೊಸ ಸೆಗ್ಮೆಂಟ್',
  'seg.autoNote': 'ಒಂದು ಸೆಗ್ಮೆಂಟ್ ತಾನಾಗಿಯೇ ನವೀಕರಿಸುತ್ತದೆ. ಯಾರಾದರೂ ನಾಳೆ ತೆರೆದರೆ, ಅವರು ತಾನಾಗಿಯೇ "Interested Leads" ಗೆ ಸೇರುತ್ತಾರೆ — ನೀವು ಎಂದಿಗೂ ಪಟ್ಟಿಯನ್ನು ಕೈಯಾರೆ ಪುನರ್ನಿರ್ಮಿಸುವುದಿಲ್ಲ.',
