  'seg.resendDesc': 'ಯಾವುದೇ ದಾಖಲಾದ ತೆರೆಯುವಿಕೆ ಇಲ್ಲದ ಪ್ರತಿಯೊಬ್ಬರಿಗೂ ಒಂದು ಹೊಸ ಅಭಿಯಾನ ರಚಿಸುತ್ತದೆ. ಏನನ್ನಾದರೂ ರಚಿಸುವ ಮೊದಲು ನಾವು ನಿಮಗೆ ನಿಖರವಾದ ಎಣಿಕೆ ತೋರಿಸುತ್ತೇವೆ ಮತ್ತು ದೃಢೀಕರಣ ಕೇಳುತ್ತೇವೆ.',
