  'camp.openEstimate': '"ತೆರೆಯುವಿಕೆ ಪತ್ತೆಯಾಗಿದೆ" ಒಂದು ಅಂದಾಜು.',
  'camp.openEstimateText': 'ಇದರರ್ಥ ಟ್ರ್ಯಾಕಿಂಗ್ ಚಿತ್ರ ಲೋಡ್ ಆಯಿತು — ಒಬ್ಬ ವ್ಯಕ್ತಿ ಖಚಿತವಾಗಿ ಇಮೇಲ್ ಓದಿದರು ಎಂದಲ್ಲ. Apple Mail Privacy Protection ಮತ್ತು ಇಂತಹ ವೈಶಿಷ್ಟ್ಯಗಳು ಚಿತ್ರಗಳನ್ನು ತಾನಾಗಿಯೇ ಲೋಡ್ ಮಾಡುತ್ತವೆ, ಮತ್ತು ಚಿತ್ರ ತಡೆಗಟ್ಟುವಿಕೆ ನಿಜವಾದ ತೆರೆಯುವಿಕೆಗಳನ್ನು ಮರೆಮಾಡುತ್ತದೆ.',
  'camp.sentMeaning': '"ಕಳುಹಿಸಲಾಗಿದೆ" ಎಂದರೆ ಯಶಸ್ವಿಯಾಗಿ ಒಪ್ಪಿಸಲಾಗಿದೆ.',
  'camp.sentMeaningText': 'ಇದರರ್ಥ ನಿಮ್ಮ ಇಮೇಲ್ ಸರ್ವರ್ ಸಂದೇಶವನ್ನು ವಿತರಣೆಗೆ ಸ್ವೀಕರಿಸಿದೆ — ಅದು ಇನ್‌ಬಾಕ್ಸ್ ತಲುಪಿತು ಎಂದಲ್ಲ. ಯಾರಾದರೂ ಅದನ್ನು ಎಂದಿಗೂ ಪಡೆಯಲಿಲ್ಲ ಎಂದು ಹೇಳಿದರೆ, ಮೊದಲು ಅವರ Spam ಫೋಲ್ಡರ್ ಪರಿಶೀಲಿಸಿ, ನಂತರ ನಿಮ್ಮ ಇಮೇಲ್ ಪೂರೈಕೆದಾರರೊಂದಿಗೆ ನಿಮ್ಮ ಕಳುಹಿಸುವ ಡೊಮೇನ್‌ನ SPF/DKIM ಸೆಟಪ್ ಪರಿಶೀಲಿಸಿ.',

